<?php declare(strict_types=1); namespace Annam; $title='Review your order'; ?>
<section class="wrap php-store-section"><h1>Review your order</h1><div class="php-cart-grid"><section class="php-white php-cart-lines"><h2><?= e($details['name']) ?></h2><p><?= e($details['phone']) ?></p><p><?= e(implode(', ',array_filter([$details['line1'],$details['line2'],$details['landmark'],$details['city'],$details['pincode']]))) ?></p><p><?= e(($quote['slot']['label']??'Shop courier').' · '.($quote['date']??'Tamil Nadu delivery')) ?></p><?php foreach($quote['lines'] as $line): ?><article><div><?= e($line['name']) ?><small> · <?= e($line['quantity']) ?> × <?= money($line['unit_price']) ?></small></div><strong><?= money($line['line_total']) ?></strong></article><?php endforeach; ?></section><section class="php-white php-cart-summary"><h2>Order total</h2><?php foreach(['subtotal'=>'Items','delivery_fee'=>'Delivery','extra_tax'=>'Additional GST'] as $key=>$label): ?><p class="php-total"><span><?= e($label) ?></span><b><?= Money::display($quote[$key]) ?></b></p><?php endforeach; ?><p class="php-total">Round off <b>₹<?= e(Money::signedDecimal($quote['round_off'])) ?></b></p><p class="php-total"><strong>Total</strong><strong><?= Money::display($quote['total']) ?></strong></p><p><?= e((new Checkout($store))->choices()[$details['payment_method']]) ?></p><form method="post" action="/checkout/place/"><?= csrf() ?><input type="hidden" name="reference" value="<?= e($reference) ?>"><button class="btn btn-primary">Place order →</button></form><a href="/checkout/">Edit details</a></section></div></section>
